import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Build compact feature values in one pass
    opp_c = 0
    my_c = 0
    cc = cd = dc = dd = 0
    for mine, opp in history:
        if opp == 'C':
            opp_c += 1
        if mine == 'C':
            my_c += 1
        if mine == 'C':
            if opp == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if opp == 'C':
                dc += 1
            else:
                dd += 1

    opp_d = n - opp_c
    last_my, last_opp = history[-1]

    # Consecutive opponent defections at the tail
    opp_run_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_run_d += 1
        else:
            break

    # Consecutive opponent cooperations at the tail
    opp_run_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_run_c += 1
        else:
            break

    # Consecutive mutual-defection run at the tail
    dd_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_run += 1
        else:
            break

    # Consecutive own defections at the tail
    my_run_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_run_d += 1
        else:
            break

    coop_ratio = opp_c / float(n)
    defect_ratio = opp_d / float(n)

    recent_len = 10 if n >= 10 else n
    recent_opp_d = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_opp_d += 1
    recent_defect_rate = recent_opp_d / float(recent_len)
    recent_opp_c = recent_len - recent_opp_d
    recent_coop_rate = recent_opp_c / float(recent_len)

    # Late-game exploitation window
    late = n >= 95

    # Heavy defector detection: punish firmly but leave small reset door
    if defect_ratio >= 0.7 or recent_defect_rate >= 0.8:
        if late and recent_coop_rate > 0.2:
            return 'D'
        # Rare, spaced reset attempts to avoid endless DD
        if opp_run_d >= 2 and (n % 7 == 0) and rng.random() < 0.10:
            return 'C'
        return 'D'

    # Predominantly cooperative opponent: sustain CC, probe only rarely
    if coop_ratio >= 0.85 and recent_defect_rate <= 0.2:
        if late:
            return 'C'
        # Sparse probing that does not derail mutual cooperation
        if n >= 6 and (n % 23 == 0) and rng.random() < 0.06:
            return 'D'
        # If our own recent defection occurred, restore C promptly
        if my_run_d >= 1:
            return 'C'
        return 'C'

    # Tail opponent defection handling
    if last_opp == 'D':
        # If opponent had a long cooperative streak before this D, treat
        # as likely noise: forgive quickly to protect CC payoff
        if opp_run_c >= 6 and opp_run_d == 1:
            return 'C'
        # Opponent just defected after we cooperated: punish, then forgive
        if last_my == 'C':
            if opp_run_d >= 3:
                # Sustained exploitation: stay in D but try resets occasionally
                if dd_run >= 1 and (n % 5 == 0) and rng.random() < 0.12:
                    return 'C'
                return 'D'
            if opp_run_d == 2:
                # Two defections in a row: one more D to deter, then reset
                if recent_coop_rate >= 0.5 and rng.random() < 0.35:
                    return 'C'
                return 'D'
            # Single defection: retaliate once with high probability
            if recent_coop_rate >= 0.6:
                # Recover quickly to preserve mutual C
                return 'D' if rng.random() < 0.6 else 'C'
            return 'D' if rng.random() < 0.8 else 'C'
        # We defected last and opponent defected too: break DD trap
        if dd_run >= 3:
            return 'C'
        if dd_run >= 1:
            # Try periodic reset based on opponent's history
            if recent_coop_rate >= 0.4:
                return 'C' if rng.random() < 0.45 else 'D'
            if (n % 4 == 0) and rng.random() < 0.20:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last
    if last_opp == 'C':
        # Opponent has been reliably cooperative: cooperate
        if recent_defect_rate <= 0.2:
            if late:
                # Only exploit a clearly non-retaliatory pattern
                if coop_ratio >= 0.95 and recent_opp_d == 0:
                    return 'D'
                return 'C'
            # Occasional probe only when pattern looks safe
            if my_run_d >= 1:
                return 'C'
            if n >= 8 and (n % 19 == 0) and recent_defect_rate == 0.0 and rng.random() < 0.05:
                return 'D'
            return 'C'
        # Mixed opponent: cooperate but punish exploitation pattern
        # If opponent just cooperated after defecting repeatedly, be cautious
        if opp_run_c == 1 and opp_run_d >= 2:
            # They may be resetting to exploit again; test cooperatively but not blindly
            if recent_defect_rate >= 0.4 and rng.random() < 0.3:
                return 'D'
            return 'C'
        # Standard punish-then-forgive
        if recent_defect_rate >= 0.5:
            return 'D' if rng.random() < 0.35 else 'C'
        if my_run_d >= 2:
            return 'C'
        # Late-game: if opponent weakly retaliatory, exploit lightly
        if late and coop_ratio >= 0.6 and recent_defect_rate <= 0.3:
            return 'D' if rng.random() < 0.35 else 'C'
        return 'C'

    return 'C'
